CREATE INDEX CONCURRENTLY IF NOT EXISTS "agent_wakeup_requests_company_pending_issue_key_idx" ON "agent_wakeup_requests" USING btree ((coalesce("payload"->>'issueId', "payload"->>'taskId', "payload"->'_paperclipWakeContext'->>'issueId')),"company_id") WHERE "agent_wakeup_requests"."status" in ('queued', 'claimed', 'deferred_issue_execution');--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "heartbeat_runs_company_unfinished_issue_key_idx" ON "heartbeat_runs" USING btree ((coalesce("context_snapshot"->>'issueId', "context_snapshot"->>'taskId', "native_issue_id"::text)),"company_id") WHERE "heartbeat_runs"."status" in ('queued', 'running', 'scheduled_retry');